    // Menormalkan koordinat UV
    vec2 p = (vUv * 2.0 - 1.0) * vec2(uTexSize.x/uTexSize.y, 1.0);

    float camZ = SPEED * uTime;
    vec2 cam = position(camZ);

    // Hitung turunan (dcam/dt)
    float camZ2 = SPEED * (uTime + DT);
    vec2 cam2 = position(camZ2);
    vec2 dcamdt = (cam2 - cam) / DT;

    vec3 f = vec3(0.0, 0.0, 0.0);

    // Ulangi melalui 250 titik (dioptimalkan untuk MilkDrop)
    for(int j = 1; j < ITERATIONS; j++) {
        float i = float(j);
