void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;

  //vRadius = fract(vRadius*2);
  vRadius = pow(vRadius,0.5)*1;


  float ang2 = fract(vAngle/6.28*7 + uTime*0.05);
  ang2 = abs(ang2*2-1);
  vec2 uv2 = 0.5 + vRadius*0.5*vec2(cos(ang2),sin(ang2));

